package org.eclipse.rdf4j.query.algebra.evaluation.iterator;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.impl.BlankNodeAllocationScope;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.eclipse.rdf4j.query.impl.RemoteBNode;
import org.junit.jupiter.api.Test;

class BindingSetSpillFileRemoteIdentityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void privateSpillPreservesRemoteIdentityAcrossStreamResetsAndRescans() {
		Object namespace = new Object();
		BNode alias = remote(namespace, "remote");
		Value nested = VF.createTripleTerm(alias, VF.createIRI("urn:p"),
				VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:q"), alias));
		Value expectedNested = VF.createTripleTerm(VF.createBNode("remote"), VF.createIRI("urn:p"),
				VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:q"), VF.createBNode("remote")));
		MapBindingSet input = new MapBindingSet();
		input.addBinding("node", alias);
		input.addBinding("nested", nested);
		input.addBinding("plain", VF.createBNode(alias.getID()));
		try (var spill = new BindingSetSpillFile("rdf4j-identity-test-", "identity regression")) {
			for (int row = 0; row < 300; row++) {
				assertTrue(spill.write(input));
			}
			assertTrue(spill.finishWriting());
			assertEquals(300L, spill.rowCount());
			for (int scan = 0; scan < 2; scan++) {
				try (var reader = spill.openReader()) {
					for (int row = 0; row < 300; row++) {
						BindingSet restored = reader.next();
						assertEquals(VF.createBNode("remote"),
								RemoteBNode.toRemoteValue(restored.getValue("node"), namespace, true, true));
						assertEquals(expectedNested,
								RemoteBNode.toRemoteValue(restored.getValue("nested"), namespace, true, true));
						assertFalse(restored.getValue("plain") instanceof RemoteBNode,
								"equal alias text must not grant the plain blank node authority");
						assertThrows(QueryEvaluationException.class,
								() -> RemoteBNode.toRemoteValue(restored.getValue("plain"), namespace, true, true));
						assertFalse(restored.hasBinding("unbound"));
					}
					assertNull(reader.next());
				}
			}
		}
	}

	@Test
	void ordinaryJavaSerializationDoesNotCarryRemoteAuthority() throws Exception {
		Object namespace = new Object();
		BNode original = remote(namespace, "remote");
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
			out.writeObject(original);
		}
		RemoteBNode restored;
		try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			restored = assertInstanceOf(RemoteBNode.class, in.readObject());
		}
		assertEquals(original.getID(), restored.getID());
		assertNull(restored.getProvenance());
		assertThrows(QueryEvaluationException.class,
				() -> RemoteBNode.toRemoteValue(restored, namespace, true, true));
	}

	@Test
	void equalAliasLabelsFromDifferentAuthoritiesAreRejectedWithinOnePrivateSpill() {
		BNode first = remote(new Object(), "first");
		BNode second = remote(new Object(), "second");
		assertEquals(first.getID(), second.getID());
		MapBindingSet firstRow = new MapBindingSet();
		firstRow.addBinding("node", first);
		MapBindingSet secondRow = new MapBindingSet();
		secondRow.addBinding("node", second);
		try (var spill = new BindingSetSpillFile("rdf4j-identity-test-", "identity regression")) {
			assertTrue(spill.write(firstRow));
			assertThrows(QueryEvaluationException.class, () -> spill.write(secondRow));
		}
	}

	private static BNode remote(Object namespace, String id) {
		return (BNode) RemoteBNode.newResponseScope(new BlankNodeAllocationScope("alias-", ignored -> false),
				VF, namespace, true).map(VF.createBNode(id));
	}
}
